from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = max(0, capacity)
        self.ttl = ttl
        self.clock = clock
        self.cache = OrderedDict()
        self.hits = 0
        self.misses = 0
        self.evictions = 0
        self.expirations = 0

    def _purge_expired(self, now: float) -> None:
        expired_keys = [
            key
            for key, entry in self.cache.items()
            if entry["expiry"] <= now
        ]
        if expired_keys:
            for key in expired_keys:
                del self.cache[key]
            self.expirations += len(expired_keys)

    def put(self, key, value) -> None:
        if self.capacity == 0:
            return

        now = self.clock()

        if key in self.cache:
            entry = self.cache[key]
            entry["value"] = value
            entry["expiry"] = now + self.ttl
            self.cache.move_to_end(key)
            return

        self._purge_expired(now)

        if len(self.cache) >= self.capacity:
            self.cache.popitem(last=False)
            self.evictions += 1

        self.cache[key] = {"value": value, "expiry": now + self.ttl}

    def get(self, key, default=None):
        if self.capacity == 0:
            self.misses += 1
            return default

        now = self.clock()

        if key not in self.cache:
            self.misses += 1
            return default

        entry = self.cache[key]

        if entry["expiry"] <= now:
            del self.cache[key]
            self.expirations += 1
            self.misses += 1
            return default

        self.cache.move_to_end(key)
        self.hits += 1
        return entry["value"]

    def __len__(self) -> int:
        if self.capacity == 0:
            return 0

        now = self.clock()
        return sum(
            1
            for entry in self.cache.values()
            if entry["expiry"] > now
        )

    def stats(self) -> dict:
        return {
            "hits": self.hits,
            "misses": self.misses,
            "evictions": self.evictions,
            "expirations": self.expirations,
        }
