import re
import unicodedata


def slugify(title: str, max_len: int = 50) -> str:
    ascii_only = unicodedata.normalize("NFKD", title).encode("ascii", "ignore").decode("ascii")
    slug = re.sub(r"[^a-z0-9]+", "-", ascii_only.lower()).strip("-")

    if not slug or max_len <= 0:
        return ""

    if len(slug) <= max_len:
        return slug

    words = slug.split("-")
    length = 0
    kept = 0

    for i, word in enumerate(words):
        needed = len(word) + (1 if i else 0)
        if length + needed > max_len:
            break
        length += needed
        kept += 1

    if kept:
        return "-".join(words[:kept])

    return slug[:max_len]
