from itertools import groupby


def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    sorted_unique = sorted(set(nums))
    parts = []

    for _, group in groupby(
        enumerate(sorted_unique), key=lambda pair: pair[1] - pair[0]
    ):
        run = [value for _, value in group]

        if len(run) >= 3:
            parts.append(f"{run[0]}..{run[-1]}")
        else:
            parts.extend(str(value) for value in run)

    return ",".join(parts)
