from collections.abc import Callable


class TokenBucket:
    def __init__(self, capacity: float, refill_per_sec: float, clock: Callable[[], float]) -> None:
        self._capacity = float(capacity)
        self._refill_per_sec = float(refill_per_sec)
        self._clock = clock
        self._tokens = float(capacity)
        self._last_refill = float(clock())

    def _refill(self) -> None:
        now = float(self._clock())
        if now <= self._last_refill:
            return

        elapsed = now - self._last_refill
        if elapsed > 0 and self._refill_per_sec > 0:
            self._tokens = min(self._capacity, self._tokens + elapsed * self._refill_per_sec)

        self._last_refill = now

    def allow(self, cost: float = 1) -> bool:
        if cost <= 0:
            return True

        self._refill()
        if self._tokens >= cost:
            self._tokens -= cost
            return True

        return False

    @property
    def tokens(self) -> float:
        self._refill()
        return float(self._tokens)
