import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_EVEN

_AMOUNT_PATTERN = re.compile(
    r'^-?\$?(?:'
    r'\d{1,3}(?:,\d{3})*|'
    r'\d+(?:\.\d*)?|'
    r'\.\d+'
    r')$'
)

def _parse_amount(amount: str) -> Decimal | None:
    if not isinstance(amount, str):
        return None

    value = amount.strip()
    if not value:
        return None

    if not _AMOUNT_PATTERN.fullmatch(value):
        return None

    normalized = value.replace("$", "").replace(",", "")

    try:
        return Decimal(normalized)
    except (InvalidOperation, ArithmeticError):
        return None

def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    if not isinstance(n, int) or n <= 0:
        return []

    customers = {}

    for row in rows:
        if not isinstance(row, dict):
            continue

        customer = row.get("customer")
        if not isinstance(customer, str):
            continue

        trimmed_customer = customer.strip()
        if not trimmed_customer:
            continue

        amount = _parse_amount(row.get("amount"))
        if amount is None:
            continue

        key = trimmed_customer.lower()
        entry = customers.get(key)

        if entry is None:
            customers[key] = [trimmed_customer, amount]
        else:
            entry[1] += amount

    items = [
        (name, total.quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN))
        for name, total in customers.values()
    ]

    items.sort(key=lambda item: (-item[1], item[0]))

    return [(name, float(total)) for name, total in items[:n]]
